promql:
(sum by (downstream_endpoint) (
    api_request_count
    {
        method = "PUT",
        endpoint = "/api/v1/admintravelservice/admintravel",
        time_window = "30m"
    }
    [30m:]
)) by (downstream_endpoint)

max by(node) (
    sum by(node, pod_name) (
        container_memory_usage_bytes{job="kubernetes", container!="POD", node=~"k8s-node2|k8s-node5", 
                                      pod_labels_service="gateway"} 
    )
)

topk(3, 
    (
      (sum by (pod) (rate(node_network_receive_drop_total{instance='10.176.122.152:10250', namespace='obs'}[5m])) 
      / 
      sum by (pod) (rate(node_network_receive_bytes_total{instance='10.176.122.152:10250', namespace='obs'}[5m]))
    ) * 100
   )
)

sum(node_num_cpus) by (node) {
  node: k8s-node1,
  node: k8s-node3
}

rate(node_procs_forked_total[5m]) without (instance) {
  k8s_pod_name: coredns-558bd4d5db,
  k8s_namespace: kube-system,
  k8s_deployment_name: coredns
}

sum by (device) (
  irate(container_fs_reads_bytes_total{service="gateway", device="/dev/sda"}[10m])
)
sum by (device) (
  irate(container_block_io_time_weighted_seconds_total{service="gateway", device="/dev/sda", direction="read"}[10m]) * 512  // Assuming each sector size is 512 bytes
)

sum by (node) (
  sum(container_memory_limit_hit{container!="POD", service="ts-admin-order-service", limit_hit="true"}) 
  * on(pod) group_left(node) kube_pod_info{}
)

topk(1, 
    irate(node_cpu{job="node", mode="total"}[1m]) / on(node) group_left() node_load1{job="node", load_average_1m < 0.8} 
    * on(node) group_left() kube_node_labels{service="gateway"}
)

label_replace(
  max by (node)(
    sum(
      node_network_receive_errors_total{device="docker0", 
        instance=~"(?i)(.*):[0-9]+"}  // assuming instance label includes node name
      )[
        24h
      ]
    )
    * on(instance) group_left(node)
    kube_pod_info{k8s_app!="", statefulset="tsdb-mysql"}
  ),
  "statefulset", "", "statefulset", "tsdb-mysql"
)

topk(1,
    sum by (node_name) (
        node_memory_bounce_bytes
        * on (pod) without (namespace, pod) kube_pod_info{statefulset="tsdb-mysql"}
    )
)

topk(3, (
  node_filesystem_free_bytes{device="/", instance=~"10.176.122.15[0-9]"}  
  / 1073741824  # Convert bytes to GB
))

sort_desc(
  sum by (instance)(node_filesystem_free_bytes{device="/dev/sda2", mountpoint="/"})
  * on(instance) group_left(node)
  kube_node_labels{label_kubernetes_io_hostname=~"k8s-node[12]"}
)
[0]

(sum by (direction, client, server) (
  increase(http_requests_total{status=~"5..x", direction="client", client="ts-gateway-service", server="ts-assurance-service"}[30m])
)) by (client, server)

max(
    node_memory_Cached_bytes{instance="10.176.122.151:9100"}
) without (instance) +
max(
    node_memory_Cached_bytes{instance="10.176.122.153:9100"}
) without (instance)
labels(max(node_memory_Cached_bytes{instance=~"10\.176\.122\.\d+:\d+"}))[
  0
], max(node_memory_Cached_bytes) by (instance)

(
  (node_filesystem_size{mountpoint="/", device=~"/dev/.*"} - increase(node_filesystem_free{mountpoint="/", device=~"/dev/.*"}[8h])) / 
  node_filesystem_size{mountpoint="/", device=~"/dev/.*"}
) * 100 > 97
AND
rate(node_disk_write_bytes_total[4h]) > 50*1024*1024

avg by (pod_name) (
  sum by (pod_name, container_name) (
    container_memory_usage_bytes{instance=~"10.176.122.161:10250", pod_name~="^ts-admin-order-service.*"}
  )
)

sum without (container) (
  sum by (pod) (
    container_memory_pagecache_bytes{pod_name=~"^ts-train-food-service.*"}
  )
)
by (node)
sum by (node) (
  node_memory_PageCache_bytes{pod_name=~"^ts-train-food-service.*"}
)

(
  sum by (container_name) (
    container_fs_limit_bytes{container="ts-payment-service", node="k8s-node2"} 
  ) - 
  sum by (container_name) (
    container_fs_usage_bytes{container="ts-payment-service", node="k8s-node2"} 
  )
) without (container_name)

avg by (container) (
  sum by (pod, container) (
    container_memory_usage_bytes{pod=~"^ts-admin-order-service-[a-zA-Z0-9]+", container!="POD"} 
  )
)

sum without (mode) (
  irate(node_cpu{instance=~"10.176.122.15[1-3]", mode!="idle"}[1m])
  * on(instance) group_left()
  node_num_cpus{instance=~"10.176.122.15[1-3]", num_cpus>=16}
)

(sum(
  rate(request_failures_total{client="ts-inside-payment-service"}[5m])
  {
    server in ("ts-order-other-service", "ts-order-service", "ts-payment-service")
  }
) by (server)) /
(sum(
  rate(requests_total{client="ts-inside-payment-service"}[5m])
  {
    server in ("ts-order-other-service", "ts-order-service", "ts-payment-service")
  }
) by (server))
> 0.05
